  it("refreshes free-roam autonomy latest as a read-only first-screen action", async () => {
    // latest 只读按钮只拉 runtime artifact 和 summary，不允许误触发自动扫图或底盘运动。
    let delayNextLatest = false;
    let resolveLatest!: (value: { ok: boolean; json: () => Promise<unknown> }) => void;
    const delayedLatest = new Promise<{ ok: boolean; json: () => Promise<unknown> }>((resolve) => {
      resolveLatest = resolve;
    });
    const baseFetch = stubWorkstationFetch();
    const mockedFetch = vi.fn((url: string, options?: RequestInit) => {
      if (url.startsWith("/api/robot-control/free-roam/autonomy/latest") && delayNextLatest) {
        delayNextLatest = false;
        return delayedLatest;
      }
      return baseFetch(url, options);
    });
    vi.stubGlobal("fetch", mockedFetch);
    const wrapper = mount(App);
    await flushPromises();
    await wrapper.vm.$nextTick();

    const button = wrapper.find('[data-testid="plain-free-roam-autonomy-latest"]');
    expect(button.exists()).toBe(true);
    expect(button.text()).toBe("刷新自由移动状态（只读）");
    expect(button.attributes("disabled")).toBeUndefined();
    const callsBeforeClick = mockedFetch.mock.calls.length;

    delayNextLatest = true;
    const latestClick = button.trigger("click");
    await wrapper.vm.$nextTick();
    expect(wrapper.find('[data-testid="plain-free-roam-autonomy-latest"]').text()).toBe("刷新中");
    expect(wrapper.find('[data-testid="plain-current-facts"]').text()).toContain(
      "自由移动：正在读取最新上车状态，返回前不把旧自由移动记录当作当前结论。",
    );
    resolveLatest({
      ok: true,
      json: async () => fixtures["/api/robot-control/free-roam/autonomy/latest"],
    });
    await latestClick;
    await flushPromises();
    await wrapper.vm.$nextTick();

    const newCalls = mockedFetch.mock.calls.slice(callsBeforeClick);
    expect(newCalls.some(([url]) => String(url).startsWith("/api/robot-control/free-roam/autonomy/latest?"))).toBe(true);
    expect(wrapper.find('[data-testid="plain-free-roam-autonomy-latest-summary"]').text()).toBe(
      "最新读取：自由移动可启动；只需现场安全确认和停止兜底；当前未在自由移动运行态；motion_ready=false 只表示尚未开始发布运动，不是启动阻塞；建图验收未就绪；还差：画面首帧、雷达新鲜、地图记录、地图画面；这不阻止先低速自由移动；runtime 地图指标：可通行 421 格，未知 98.2%。",
    );
    expect(newCalls.some(([url]) => String(url).startsWith("/api/robot-control/free-roam/autonomy/start?"))).toBe(false);
    expect(newCalls.some(([url]) => String(url).startsWith("/api/robot-control/free-roam/autonomy/stop?"))).toBe(false);
    expect(newCalls.some(([url]) => String(url).startsWith("/api/robot-control/base/manual?"))).toBe(false);
    expect(newCalls.some(([url]) => String(url).includes("/cmd_vel"))).toBe(false);
  });

