        remote_endpoint: "/api/map/start",
        remote_method: "POST",
        remote_http_status: 200,
        status: "loaded_fail_closed_summary",
        map_count: 0,
        map_names: [],
        map_quality_summary: {
          status: "not_loaded",
          message: "地图记录已启动，保存后再检查质量。",
          checked_yaml_count: 0,
          usable_map_count: 0,
          no_free_cell_map_count: 0,
          analysis_failed_count: 0,
        },
