  it("marks stale facts when a plain refresh fails after a prior summary", async () => {
    // 现场上位机卡住时不能继续把上一拍相机/雷达/Nav2 文案伪装成实时事实；失败只改变展示，不触发运动。
    const mockedFetch = stubWorkstationFetch();
    const originalFetch = mockedFetch.getMockImplementation();
    let rejectNextSummary = false;
    mockedFetch.mockImplementation((url: string, options?: RequestInit) => {
      if (rejectNextSummary && String(url).startsWith("/api/robot-control/summary?")) {
        rejectNextSummary = false;
        return Promise.reject(new Error("summary_timeout_fixture"));
      }
      if (!originalFetch) {
        throw new Error("missing default fetch mock");
      }
      return originalFetch(url, options);
    });

    const wrapper = mount(App);
    await flushPromises();
    await wrapper.vm.$nextTick();
    expect(wrapper.find('[data-testid="plain-current-facts"]').text()).not.toContain("上一次读数");

    const radarProofCallsBefore = mockedFetch.mock.calls.filter(([url]) => String(url).startsWith("/api/robot-control/radar/scan-proof/refresh?")).length;
    const mapPreviewCallsBefore = mockedFetch.mock.calls.filter(([url]) => String(url).startsWith("/api/robot-control/map/preview?")).length;
    rejectNextSummary = true;
    await wrapper.find('[data-testid="robot-api-refresh"]').trigger("click");
    await flushPromises();
    await wrapper.vm.$nextTick();

    expect(wrapper.find('[data-testid="plain-current-facts"]').text()).toContain("小车：这次连接/刷新失败，下面可能是上一次读数；先恢复网络或上位机服务后再刷新。");
    expect(wrapper.find('[data-testid="plain-current-facts"]').text()).not.toContain("summary_timeout_fixture");
    expect(wrapper.find('[role="alert"]').text()).toContain("summary_timeout_fixture");
    expect(mockedFetch.mock.calls.filter(([url]) => String(url).startsWith("/api/robot-control/radar/scan-proof/refresh?")).length).toBe(radarProofCallsBefore);
    expect(mockedFetch.mock.calls.filter(([url]) => String(url).startsWith("/api/robot-control/map/preview?")).length).toBe(mapPreviewCallsBefore);
    expect(mockedFetch.mock.calls.some(([url]) => String(url).startsWith("/api/robot-control/base/manual?"))).toBe(false);
    expect(mockedFetch.mock.calls.some(([url]) => String(url).startsWith("/api/robot-control/nav2/goal/execute?"))).toBe(false);
    expect(mockedFetch.mock.calls.some(([url]) => String(url).startsWith("/api/robot-control/delivery/complete?"))).toBe(false);
    expect(mockedFetch.mock.calls.some(([url]) => String(url).includes("/cmd_vel"))).toBe(false);
  });

  it("fails closed when the browser-side summary request times out", async () => {
    // PC Node 自己无响应时，浏览器也必须退出 loading，不能让普通首屏一直等；超时仍不触发任何控制 endpoint。
    vi.useFakeTimers();
    const mockedFetch = stubWorkstationFetch();
    const originalFetch = mockedFetch.getMockImplementation();
    let summarySignalObserved = false;
    mockedFetch.mockImplementation((url: string, options?: RequestInit) => {
      if (String(url).startsWith("/api/robot-control/summary?")) {
        return new Promise((_resolve, reject) => {
          const signal = options?.signal;
          summarySignalObserved = Boolean(signal);
          signal?.addEventListener("abort", () => {
            reject(Object.assign(new Error("aborted"), { name: "AbortError" }));
          }, { once: true });
        });
      }
      if (!originalFetch) {
        throw new Error("missing default fetch mock");
      }
      return originalFetch(url, options);
    });

    const wrapper = mount(App);
    await vi.advanceTimersByTimeAsync(12000);
    await flushPromises();
    await wrapper.vm.$nextTick();

    expect(summarySignalObserved).toBe(true);
    expect(wrapper.find('[role="alert"]').text()).toContain("client_timeout_12000ms");
    expect(wrapper.find('[data-testid="plain-current-facts"]').text()).toContain("小车：连接/刷新失败；先检查小车电源、网络和上位机服务。");
    expect(wrapper.find('[data-testid="plain-current-facts"]').text()).not.toContain("client_timeout_12000ms");
    expect(wrapper.find('[data-testid="robot-api-refresh"]').attributes("disabled")).toBeUndefined();
    expect(mockedFetch.mock.calls.some(([url]) => String(url).startsWith("/api/robot-control/base/manual?"))).toBe(false);
    expect(mockedFetch.mock.calls.some(([url]) => String(url).startsWith("/api/robot-control/nav2/goal/execute?"))).toBe(false);
    expect(mockedFetch.mock.calls.some(([url]) => String(url).startsWith("/api/robot-control/free-roam/autonomy/start?"))).toBe(false);
    expect(mockedFetch.mock.calls.some(([url]) => String(url).startsWith("/api/robot-control/delivery/complete?"))).toBe(false);
    expect(mockedFetch.mock.calls.some(([url]) => String(url).includes("/cmd_vel"))).toBe(false);
  });

