    expect(sharedPreviewProof.attributes("data-sends-motion-when-clicked")).toBe("false");
    expect(sharedPreviewProof.attributes("data-starts-camera-exclusive-capture")).toBe("false");
    expect(sharedPreviewProof.text()).toContain("共享预览证明：单上游共享");
    expect(sharedPreviewProof.text()).toContain("不是页面独占");
    expect(sharedPreviewProof.text()).toContain("相机服务自己持有设备但没有读到首帧");
    expect(sharedPreviewProof.text()).toContain("检查 USB、摄像头输入或供电");
