    await wrapper.find('[data-testid="keyboard-control-arm"]').trigger("click");
    await flushPromises();
    await wrapper.vm.$nextTick();

    stallSummary = true;
    document.body.dispatchEvent(new KeyboardEvent("keydown", { key: "w", bubbles: true }));
    await flushPromises();
    await wrapper.vm.$nextTick();
