    expect(wrapper.find('[data-testid="robot-camera-mjpeg-preview"]').attributes("data-shared-preview-auto-joins")).toBe("true");
    expect(wrapper.find('[data-testid="robot-camera-mjpeg-preview"]').attributes("data-fixed-shared-preview-endpoint")).toBe("/api/robot-control/camera/mjpeg");
    expect(wrapper.find('[data-testid="robot-camera-mjpeg-preview"]').attributes("data-fixed-shared-preview-status-endpoint")).toBe("/api/robot-control/camera/mjpeg/status");
    expect(wrapper.find('[data-testid="robot-camera-wysiwyg-status"]').text()).toBe("画面状态：当前显示 MJPEG 实时画面。MJPEG 实时流已显示。");
    const mjpegCameraFrameProof = wrapper.find('[data-testid="plain-camera-current-frame-proof"]');
    expect(mjpegCameraFrameProof.text()).toBe("画面验收：本页已显示 MJPEG 实时帧；2 个页面共用同一条上游流；不是浏览器独占。下一步：继续监看当前画面。");
    expect(mjpegCameraFrameProof.attributes("data-state")).toBe("本页已显示");
